import csv
from io import StringIO

def solve(x):
    data = {}
    lines = x.strip().split('\n')
    reader = csv.DictReader(StringIO('\n'.join(lines)))
    for i, row in enumerate(reader, 1):
        label = row['label']
        value = int(row['value'])
        if label not in data:
            data[label] = i
        else:
            if value < data[label]:
                data[label] = i
    return data
